function longestOnesAfterDeletion(bits: number[]): number {
  let best = 0;
  for (let del = 0; del < bits.length; del++) {
    let run = 0;
    for (let i = 0; i < bits.length; i++) {
      if (i === del) continue;
      run = bits[i] === 1 ? run + 1 : 0;
      best = Math.max(best, run);
    }
  }
  return best;
}

