function longestOnesAfterDeletion(bits: number[]): number {
  let left = 0, zeros = 0, best = 0;
  for (let right = 0; right < bits.length; right++) {
    if (bits[right] === 0) zeros++;
    while (zeros > 1) {
      if (bits[left] === 0) zeros--;
      left++;
    }
    best = Math.max(best, right - left); // window length minus the deleted element
  }
  return best;
}

